const dashboardHTML = `<!doctype html>
<html lang="fr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>c2blue · DNS live</title>
<style>
:root{color-scheme:dark;--bg:#08111f;--panel:#101d30;--panel2:#15263c;--line:#29415d;--text:#e8f0fa;--muted:#9eb1c8;--cyan:#55d6be;--amber:#ffca6a;--red:#ff7b8a;--blue:#79aaff}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 15% 0,#122945 0,var(--bg) 42%);color:var(--text);font:15px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}header{display:flex;align-items:center;justify-content:space-between;padding:28px 36px;border-bottom:1px solid var(--line);background:#08111fdd;position:sticky;top:0;z-index:3;backdrop-filter:blur(14px)}h1{font-size:25px;margin:0;letter-spacing:-.03em}h1 span{color:var(--cyan)}header p{margin:3px 0 0;color:var(--muted)}.live{display:flex;align-items:center;gap:8px;color:var(--cyan);font-weight:650}.dot{width:9px;height:9px;border-radius:50%;background:var(--cyan);box-shadow:0 0 14px var(--cyan)}main{padding:26px 36px;max-width:1900px;margin:auto}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.card,.panel{background:linear-gradient(145deg,var(--panel),#0d1929);border:1px solid var(--line);border-radius:14px;box-shadow:0 10px 35px #0003}.card{padding:18px 21px}.card label{display:block;color:var(--muted);font-size:13px;text-transform:uppercase;letter-spacing:.08em}.card strong{display:block;font-size:31px;line-height:1.2;margin-top:5px;font-variant-numeric:tabular-nums}.card small{color:var(--muted)}.layout{display:grid;grid-template-columns:300px minmax(0,1fr);gap:18px;margin-top:18px}.panel{overflow:hidden}.panel h2{font-size:16px;margin:0;padding:16px 19px;border-bottom:1px solid var(--line)}.runs{padding:8px;max-height:380px;overflow:auto}.run{display:block;width:100%;text-align:left;padding:11px 12px;margin:3px 0;border:1px solid transparent;border-radius:9px;background:transparent;color:var(--text);cursor:pointer}.run:hover,.run:focus{background:var(--panel2);border-color:var(--line)}.run code{display:block;color:var(--cyan);font-size:13px}.run small{color:var(--muted)}.run .done{color:var(--amber)}.filters{display:flex;gap:10px;padding:14px 18px;border-bottom:1px solid var(--line)}.evicted{margin-left:auto;display:flex;align-items:center;gap:6px;color:var(--muted);font-size:13px;white-space:nowrap}input{width:100%;background:#091525;border:1px solid var(--line);color:var(--text);border-radius:8px;padding:9px 12px;font:inherit}button.secondary{width:auto;white-space:nowrap;background:var(--panel2);color:var(--text);border:1px solid var(--line);border-radius:8px;padding:8px 13px;cursor:pointer}.tablewrap{overflow:auto;max-height:550px}table{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}th{position:sticky;top:0;background:#122238;text-align:left;color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.05em}th,td{padding:10px 12px;border-bottom:1px solid #21364f;white-space:nowrap}td.qname{max-width:390px;overflow:hidden;text-overflow:ellipsis}tbody tr{cursor:pointer}tbody tr:hover,tbody tr.selected{background:#1b3049}.tag{display:inline-block;padding:2px 7px;border-radius:6px;background:#1c3450;color:var(--blue);font-size:12px}.tag.alert{background:#482536;color:var(--red)}.tag.query{background:#153c3b;color:var(--cyan)}.muted{color:var(--muted)}.reason{margin-top:18px;padding:20px}.reason h2{padding:0;border:0}.reasongrid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.reason h3{font-size:13px;text-transform:uppercase;letter-spacing:.06em;color:var(--cyan);margin:14px 0 6px}.reason p,.reason li{color:#c8d6e7}.reason ul{margin:5px 0;padding-left:20px}.facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.fact{background:#0a1626;border:1px solid var(--line);border-radius:8px;padding:8px 10px}.fact span{display:block;color:var(--muted);font-size:12px}.fact code{overflow-wrap:anywhere}details{margin-top:14px;color:var(--muted)}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#07111e;padding:12px;border-radius:8px;color:#c8d6e7;max-height:160px;overflow:auto}.status{margin-left:14px;color:var(--muted)}.empty{padding:24px;color:var(--muted);text-align:center}@media(max-width:1100px){.layout{grid-template-columns:1fr}.reasongrid{grid-template-columns:1fr}.cards{grid-template-columns:repeat(2,1fr)}}@media(max-width:650px){header,main{padding-left:16px;padding-right:16px}.cards{grid-template-columns:1fr}.facts{grid-template-columns:1fr}}
</style>
</head>
<body>
<header><div><h1><span>c2blue</span> · DNS live</h1><p>Corrélation IP:port, évaluation des octets et preuves UDP reconstituées</p></div><div class="live"><i class="dot"></i> temps réel <span id="health" class="status">connexion…</span></div></header>
<main>
<section class="cards">
<div class="card"><label>Requêtes reçues</label><strong id="received">0</strong><small>direction query</small></div>
<div class="card"><label>Réponses</label><strong id="responses">0</strong><small>journalisées avant émission UDP</small></div>
<div class="card"><label>Alertes</label><strong id="alerts">0</strong><small>motif autre que REASON_NONE</small></div>
<div class="card"><label>Débit mesuré</label><strong id="rate">—</strong><small>événements/s sur horodatages observés</small></div>
</section>
<div class="layout">
<aside class="panel"><h2>Runs enregistrés</h2><div id="runs" class="runs"><div class="empty">Aucun run</div></div></aside>
<section class="panel"><h2>Événements DNS</h2><div class="filters"><input id="filter" type="search" placeholder="Filtrer par run_id (vide = sources inconnues incluses)" aria-label="Filtre run_id"><button id="clear" class="secondary">Tous les runs</button><span id="evicted" class="evicted">X-Events-Evicted · éviction mémoire : <span id="evictedCount">0</span></span></div><div class="tablewrap"><table><thead><tr><th>#</th><th>Direction</th><th>Run / kind</th><th>QNAME</th><th>Classe</th><th>Corrélation</th><th>Horodatage</th></tr></thead><tbody id="events"></tbody></table><div id="empty" class="empty">En attente de datagrammes UDP…</div></div></section>
</div>
<section class="panel reason"><h2>Pourquoi cette alerte ?</h2><div id="reason" class="muted">Sélectionner un événement pour distinguer les faits observés, le mécanisme du classifieur et ses gardes bénignes.</div></section>
</main>
<script>
'use strict';
const observed=[];let selectedSequence=0;let lastSequence=0;let guides=[];
const byID=id=>document.getElementById(id);
const text=(tag,value,className)=>{const node=document.createElement(tag);node.textContent=value;if(className)node.className=className;return node};
async function api(path){const response=await fetch(path,{credentials:'same-origin',headers:{'Accept':'application/json'}});if(!response.ok)throw new Error('HTTP '+response.status);return response.json()}
function filtered(){const runID=byID('filter').value.trim();return observed.filter(event=>!runID||event.run_id===runID)}
function renderRuns(runs){const host=byID('runs');host.replaceChildren();if(!runs.length){host.append(text('div','Aucun run','empty'));return}for(const run of runs){const button=text('button','','run');button.type='button';button.append(text('code',run.run_id));button.append(text('small',run.kind+' · '+run.source_ip+':'+run.source_port));button.append(document.createElement('br'));button.append(text('small',run.finished?'terminé':'actif',run.finished?'done':''));button.onclick=()=>{byID('filter').value=run.run_id;renderEvents()};host.append(button)}}
function renderEvents(){const events=filtered();const host=byID('events');host.replaceChildren();byID('empty').hidden=events.length>0;let received=0,responses=0,alerts=0;for(const event of events){if(event.direction==='query')received++;if(event.direction==='response')responses++;if(event.reason_code!=='REASON_NONE')alerts++;const row=document.createElement('tr');row.dataset.sequence=event.sequence;if(event.sequence===selectedSequence)row.className='selected';row.append(text('td',event.sequence));const direction=text('td',event.direction,event.direction==='query'?'tag query':'tag');row.append(direction);row.append(text('td',(event.run_id||'∅')+' / '+event.kind));row.append(text('td',event.qname||'—','qname'));row.append(text('td',event.class,event.reason_code==='REASON_NONE'?'tag':'tag alert'));row.append(text('td',event.run_id?'IP:port enregistré':'source inconnue','muted'));row.append(text('td',new Date(event.timestamp_ns/1e6).toLocaleTimeString(),'muted'));row.onclick=()=>{selectedSequence=event.sequence;renderEvents();renderReason(event)};host.append(row)}byID('received').textContent=received;byID('responses').textContent=responses;byID('alerts').textContent=alerts;if(events.length>=2){const span=events[events.length-1].timestamp_ns-events[0].timestamp_ns;byID('rate').textContent=span>0?((events.length-1)*1e9/span).toFixed(1):'—'}else byID('rate').textContent='—'}
function listBlock(title,values){const section=document.createElement('section');section.append(text('h3',title));const list=document.createElement('ul');for(const value of values||[])list.append(text('li',value));section.append(list);return section}
function renderReason(event){const host=byID('reason');host.replaceChildren();const guide=guides.find(item=>item.reason_code===event.reason_code);const heading=text('p',event.class+' · '+event.reason_code+' · '+event.direction);host.append(heading);const correlation=text('p','run_id='+(event.run_id||'∅')+' · kind='+event.kind+' · '+(event.run_id?'corrélé au couple IP:port enregistré':'source non enregistrée'),'muted');host.append(correlation);const grid=document.createElement('div');grid.className='reasongrid';const mechanism=document.createElement('section');mechanism.append(text('h3','Mécanisme'));mechanism.append(text('p',guide?guide.mechanism:'Aucune alerte : le classifieur n’a retenu aucun motif.'));if(guide){mechanism.append(listBlock('Seuils réels',guide.thresholds));mechanism.append(listBlock('Fenêtres',guide.windows));mechanism.append(listBlock('Gardes bénignes',guide.benign_guards))}grid.append(mechanism);const facts=document.createElement('section');facts.append(text('h3','Faits observés'));const factGrid=document.createElement('div');factGrid.className='facts';const entries=[['QNAME',event.qname||'∅'],['QTYPE',event.qtype],['TXID',event.txid],['Sous-domaine',event.subdomain_len+' octets'],['Labels',event.label_count],['Label maximal',event.max_label_len+' octets'],['Answers',event.answer_count],['RDATA cumulé',event.rdata_bytes+' octets'],['Décision',event.decision],['SHA-256',event.packet_sha256],['Parse error',event.parse_error||'∅'],['Source',event.src_ip+':'+event.src_port],['Destination',event.dst_ip+':'+event.dst_port]];for(const [name,value] of entries){const card=document.createElement('div');card.className='fact';card.append(text('span',name));card.append(text('code',String(value)));factGrid.append(card)}facts.append(factGrid);if(guide)facts.append(listBlock('Mesures du classifieur',guide.measurements));grid.append(facts);host.append(grid)}
async function pollEvents(){try{const response=await fetch('/dashboard/api/events?after='+lastSequence,{credentials:'same-origin',headers:{'Accept':'application/json'}});if(!response.ok)throw new Error('HTTP '+response.status);const events=await response.json();const evicted=response.headers.get('X-Events-Evicted');if(evicted!==null)byID('evictedCount').textContent=evicted;for(const event of events){observed.push(event);lastSequence=Math.max(lastSequence,event.sequence)}renderEvents();byID('health').textContent='à jour'}catch(error){byID('health').textContent='API indisponible'}}
async function pollRuns(){try{renderRuns(await api('/dashboard/api/runs'))}catch(error){byID('health').textContent='API indisponible'}}
byID('filter').addEventListener('input',renderEvents);byID('clear').onclick=()=>{byID('filter').value='';renderEvents()};
(async()=>{try{guides=await api('/dashboard/api/reasons')}catch(error){guides=[]}await pollRuns();await pollEvents();setInterval(pollEvents,1000);setInterval(pollRuns,2000)})();
</script>
</body>
</html>`

